1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
2	// Node built-ins only. Run with `node server.mjs`.
3	import { createServer } from 'node:http';
4	import { readFileSync } from 'node:fs';
5	import { readFile, writeFile } from 'node:fs/promises';
6	import { resolve } from 'node:path';
7	
8	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
9	const HOST = '127.0.0.1';
10	const DEFAULT_PORT = 3000;
11	const MAX_PORT = 65535;
12	const MAX_BODY_BYTES = 10000;
13	const MAX_TITLE_LENGTH = 80;
14	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
15	const BOOKINGS_PATH = '/api/bookings';
16	const BOOKING_ITEM_PREFIX = '/api/bookings/';
17	const JSON_TYPE = 'application/json; charset=utf-8';
18	const PAGE_FILES = Object.freeze({
19	  '/': { url: new URL('./public/index.html', import.meta.url), type: 'text/html; charset=utf-8' },
20	  '/app.js': { url: new URL('./public/app.js', import.meta.url), type: 'text/javascript; charset=utf-8' },
21	});
22	
23	const MSG = Object.freeze({
24	  contentType: 'content type must be application/json',
25	  tooLarge: 'body too large',
26	  notObject: 'body must be a JSON object',
27	  room: `room must be one of ${ROOMS.join(', ')}`,
28	  title: `title must be 1 to ${MAX_TITLE_LENGTH} characters`,
29	  date: 'date must be a valid YYYY-MM-DD date',
30	  start: 'start must be HH:MM',
31	  end: 'end must be HH:MM',
32	  order: 'end must be after start',
33	  bookingNotFound: 'booking not found',
34	  notFound: 'not found',
35	  method: 'method not allowed',
36	  internal: 'internal error',
37	});
38	
39	/** Thrown by a POST rule; carries the reply status and message. */
40	class RuleError extends Error {
41	  constructor(status, message) {
42	    super(message);
43	    this.status = status;
44	  }
45	}
46	
47	// ---------- field validation ----------
48	
49	function isValidDate(value) {
50	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
51	  const [year, month, day] = value.split('-').map(Number);
52	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
53	  const daysInMonth = [31, year % 4 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
54	  return day <= daysInMonth[month - 1];
55	}
56	
57	function isValidTime(value) {
58	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
59	  const [hours, minutes] = value.split(':').map(Number);
60	  return hours <= 23 && minutes <= 59;
61	}
62	
63	function isValidTitle(value) {
64	  return typeof value === 'string' && value.length >= 1 && value.length <= MAX_TITLE_LENGTH;
65	}
66	
67	function isPlainObject(value) {
68	  return typeof value === 'object' && value !== null && !Array.isArray(value);
69	}
70	
71	function hasExactKeys(object, keys) {
72	  const own = Object.keys(object);
73	  return own.length === keys.length && keys.every((key) => Object.hasOwn(object, key));
74	}
75	
76	function ownField(object, key) {
77	  return Object.hasOwn(object, key) ? object[key] : undefined;
78	}
79	
80	function findOverlap(bookings, { room, date, start, end }) {
81	  return bookings
82	    .filter((b) => b.room === room && b.date === date && b.start < end && start < b.end)
83	    .reduce((earliest, b) => (earliest === undefined || b.start < earliest.start ? b : earliest), undefined);
84	}
85	
86	// ---------- data file ----------
87	
88	function isStoredBooking(value, nextId) {
89	  return (
90	    isPlainObject(value) &&
91	    hasExactKeys(value, BOOKING_KEYS) &&
92	    Number.isSafeInteger(value.id) && value.id >= 1 && value.id < nextId &&
93	    ROOMS.includes(value.room) &&
94	    isValidTitle(value.title) && value.title === value.title.trim() &&
95	    isValidDate(value.date) && isValidTime(value.start) && isValidTime(value.end) &&
96	    value.start < value.end
97	  );
98	}
99	
100	function isValidState(data) {
101	  if (!isPlainObject(data) || !hasExactKeys(data, ['nextId', 'bookings'])) return false;
102	  const { nextId, bookings } = data;
103	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
104	  if (!bookings.every((b) => isStoredBooking(b, nextId))) return false;
105	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return false;
106	  return bookings.every((b, i) => findOverlap(bookings.slice(0, i), b) === undefined);
107	}
108	
109	/** Returns the stored state, an empty state on ENOENT, or null when the file is unusable. */
110	function loadState(path) {
111	  let text;
112	  try {
113	    text = readFileSync(path, 'utf8');
114	  } catch (error) {
115	    if (error.code === 'ENOENT') return { nextId: 1, bookings: [] };
116	    return null;
117	  }
118	  try {
119	    const data = JSON.parse(text);
120	    return isValidState(data) ? data : null;
121	  } catch {
122	    return null;
123	  }
124	}
125	
126	function saveState(path, state) {
127	  return writeFile(path, `${JSON.stringify(state, null, 2)}\n`);
128	}
129	
130	// ---------- HTTP helpers ----------
131	
132	function sendJson(res, status, payload) {
133	  const body = JSON.stringify(payload);
134	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
135	  res.end(body);
136	}
137	
138	function sendError(res, status, message) {
139	  sendJson(res, status, { error: message });
140	}
141	
142	/** Reads the whole body; keeps at most MAX_BODY_BYTES but counts every byte received. */
143	function readBody(req) {
144	  return new Promise((resolveBody, rejectBody) => {
145	    const chunks = [];
146	    let received = 0;
147	    req.on('data', (chunk) => {
148	      if (received + chunk.length <= MAX_BODY_BYTES) chunks.push(chunk);
149	      received += chunk.length;
150	    });
151	    req.on('end', () => resolveBody({ size: received, buffer: Buffer.concat(chunks) }));
152	    req.on('error', rejectBody);
153	    req.on('close', () => {
154	      if (!req.complete) rejectBody(new Error('request aborted'));
155	    });
156	  });
157	}
158	
159	function isJsonContentType(header) {
160	  if (typeof header !== 'string') return false;
161	  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
162	  return media.toLowerCase() === 'application/json';
163	}
164	
165	// ---------- booking logic ----------
166	
167	function sortBookings(bookings) {
168	  const key = (b) => [b.date, b.start, ROOMS.indexOf(b.room)];
169	  return [...bookings].sort((a, b) => {
170	    const [ka, kb] = [key(a), key(b)];
171	    const index = ka.findIndex((value, i) => value !== kb[i]);
172	    if (index === -1) return 0;
173	    return ka[index] < kb[index] ? -1 : 1;
174	  });
175	}
176	
177	function parseBookingRequest(headers, body, bookings) {
178	  if (!isJsonContentType(headers['content-type'])) throw new RuleError(415, MSG.contentType);
179	  if (body.size > MAX_BODY_BYTES) throw new RuleError(413, MSG.tooLarge);
180	  let data;
181	  try {
182	    data = JSON.parse(body.buffer.toString('utf8'));
183	  } catch {
184	    throw new RuleError(400, MSG.notObject);
185	  }
186	  if (!isPlainObject(data)) throw new RuleError(400, MSG.notObject);
187	  const [room, rawTitle, date, start, end] = ['room', 'title', 'date', 'start', 'end'].map((k) => ownField(data, k));
188	  if (typeof room !== 'string' || !ROOMS.includes(room)) throw new RuleError(400, MSG.room);
189	  const title = typeof rawTitle === 'string' ? rawTitle.trim() : undefined;
190	  if (!isValidTitle(title)) throw new RuleError(400, MSG.title);
191	  if (!isValidDate(date)) throw new RuleError(400, MSG.date);
192	  if (!isValidTime(start)) throw new RuleError(400, MSG.start);
193	  if (!isValidTime(end)) throw new RuleError(400, MSG.end);
194	  if (end <= start) throw new RuleError(400, MSG.order);
195	  const clash = findOverlap(bookings, { room, date, start, end });
196	  if (clash) throw new RuleError(409, `room is already booked from ${clash.start} to ${clash.end}`);
197	  return { room, title, date, start, end };
198	}
199	
200	// ---------- route handlers ----------
201	
202	function createHandlers(store) {
203	  function listBookings(res, query) {
204	    const params = new URLSearchParams(query);
205	    const all = store.get().bookings;
206	    if (!params.has('date')) return sendJson(res, 200, { bookings: sortBookings(all) });
207	    const date = params.get('date');
208	    if (!isValidDate(date)) return sendError(res, 400, MSG.date);
209	    return sendJson(res, 200, { bookings: sortBookings(all.filter((b) => b.date === date)) });
210	  }
211	
212	  async function createBooking(req, res, body) {
213	    const state = store.get();
214	    let fields;
215	    try {
216	      fields = parseBookingRequest(req.headers, body, state.bookings);
217	    } catch (error) {
218	      if (error instanceof RuleError) return sendError(res, error.status, error.message);
219	      throw error;
220	    }
221	    const booking = { id: state.nextId, ...fields };
222	    await store.commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
223	    return sendJson(res, 201, booking);
224	  }
225	
226	  async function deleteBooking(res, idText) {
227	    const state = store.get();
228	    const target = /^[1-9][0-9]*$/.test(idText)
229	      ? state.bookings.find((b) => String(b.id) === idText)
230	      : undefined;
231	    if (!target) return sendError(res, 404, MSG.bookingNotFound);
232	    await store.commit({ ...state, bookings: state.bookings.filter((b) => b !== target) });
233	    res.writeHead(204);
234	    return res.end();
235	  }
236	
237	  async function servePage(res, page) {
238	    const content = await readFile(page.url);
239	    res.writeHead(200, { 'Content-Type': page.type, 'Content-Length': content.length });
240	    res.end(content);
241	  }
242	
243	  return { listBookings, createBooking, deleteBooking, servePage };
244	}
245	
246	function isBookingItemPath(path) {
247	  if (!path.startsWith(BOOKING_ITEM_PREFIX)) return false;
248	  const rest = path.slice(BOOKING_ITEM_PREFIX.length);
249	  return rest.length > 0 && !rest.includes('/');
250	}
251	
252	/** Picks the handler for a request; returns a function producing the reply. */
253	function route(handlers, req, res, body) {
254	  const target = req.url;
255	  const mark = target.indexOf('?');
256	  const path = mark === -1 ? target : target.slice(0, mark);
257	  const query = mark === -1 ? '' : target.slice(mark + 1);
258	  const { method } = req;
259	  const only = (allowed, run) => () => (method === allowed ? run() : sendError(res, 405, MSG.method));
260	
261	  if (path === '/api/rooms') return only('GET', () => sendJson(res, 200, { rooms: ROOMS }));
262	  if (path === BOOKINGS_PATH) {
263	    if (method === 'POST') return () => handlers.createBooking(req, res, body);
264	    return only('GET', () => handlers.listBookings(res, query));
265	  }
266	  if (isBookingItemPath(path)) {
267	    return only('DELETE', () => handlers.deleteBooking(res, path.slice(BOOKING_ITEM_PREFIX.length)));
268	  }
269	  if (Object.hasOwn(PAGE_FILES, path)) return only('GET', () => handlers.servePage(res, PAGE_FILES[path]));
270	  return () => sendError(res, 404, MSG.notFound);
271	}
272	
273	// ---------- server ----------
274	
275	/** Runs tasks one at a time, in arrival order. */
276	function createQueue() {
277	  let tail = Promise.resolve();
278	  return (task) => {
279	    const run = tail.then(task);
280	    // The caller handles run's failure; the tail only needs to settle so the next task can start.
281	    tail = run.then(() => undefined, () => undefined);
282	    return run;
283	  };
284	}
285	
286	function createStore(path, initial) {
287	  let state = initial;
288	  return {
289	    get: () => state,
290	    async commit(next) {
291	      await saveState(path, next);
292	      state = next;
293	    },
294	  };
295	}
296	
297	function createRequestListener(store) {
298	  const handlers = createHandlers(store);
299	  const enqueue = createQueue();
300	  return async (req, res) => {
301	    let body;
302	    try {
303	      body = await readBody(req);
304	    } catch {
305	      req.destroy();
306	      return;
307	    }
308	    try {
309	      await enqueue(() => route(handlers, req, res, body)());
310	    } catch (error) {
311	      process.stderr.write(`internal error: ${error?.code ?? error?.name ?? 'unknown'}\n`);
312	      if (!res.headersSent) sendError(res, 500, MSG.internal);
313	      else res.destroy();
314	    }
315	  };
316	}
317	
318	function parsePort(raw) {
319	  if (raw === undefined || raw === '') return DEFAULT_PORT;
320	  if (!/^[0-9]+$/.test(raw)) return null;
321	  const port = Number(raw);
322	  return port <= MAX_PORT ? port : null;
323	}
324	
325	function fail(message) {
326	  process.stderr.write(`${message}\n`);
327	  process.exitCode = 1;
328	}
329	
330	function main() {
331	  const port = parsePort(process.env.PORT);
332	  if (port === null) return fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
333	  const dataName = process.env.DATA_FILE || 'bookings.json';
334	  const dataPath = resolve(process.cwd(), dataName);
335	  const initial = loadState(dataPath);
336	  if (initial === null) return fail(`cannot read data file ${dataName}`);
337	
338	  const server = createServer(createRequestListener(createStore(dataPath, initial)));
339	  const onBindError = (error) => fail(`cannot listen on port ${port}: ${error.code ?? 'unknown error'}`);
340	  server.once('error', onBindError);
341	  server.listen(port, HOST, () => {
342	    server.off('error', onBindError);
343	    server.on('error', (error) => process.stderr.write(`server error: ${error.code ?? 'unknown'}\n`));
344	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
345	  });
346	  return undefined;
347	}
348	
349	main();
