1	// Room bookings page script. Classic script: sets up at once, no load event.
2	// Uses only: fetch (method/headers/body, status, json()), document.getElementById,
3	// document.createElement, and element textContent/value/type/disabled/append/
4	// replaceChildren/addEventListener, plus event.preventDefault.
5	(function () {
6	  'use strict';
7	
8	  const UNREACHABLE = 'Could not reach the server.';
9	  const FALLBACK_ERROR = 'Request failed.';
10	
11	  const form = document.getElementById('booking-form');
12	  const roomSelect = document.getElementById('room');
13	  const titleInput = document.getElementById('title');
14	  const dateInput = document.getElementById('date');
15	  const startInput = document.getElementById('start');
16	  const endInput = document.getElementById('end');
17	  const bookButton = document.getElementById('book');
18	  const filterDate = document.getElementById('filter-date');
19	  const showAllButton = document.getElementById('show-all');
20	  const bookingList = document.getElementById('booking-list');
21	  const errorBox = document.getElementById('error');
22	
23	  let listSequence = 0;
24	
25	  // Resolves to { status, body } or to null when there is no usable reply
26	  // (fetch failed, or a non-204 body could not be read as JSON).
27	  async function send(url, options) {
28	    let response;
29	    try {
30	      response = await fetch(url, options);
31	    } catch {
32	      return null;
33	    }
34	    const status = response.status;
35	    if (status === 204) {
36	      return { status, body: null };
37	    }
38	    try {
39	      const body = await response.json();
40	      return { status, body };
41	    } catch {
42	      return null;
43	    }
44	  }
45	
46	  function isPlainObject(value) {
47	    return typeof value === 'object' && value !== null && !Array.isArray(value);
48	  }
49	
50	  function errorMessage(body) {
51	    if (isPlainObject(body) && typeof body.error === 'string') {
52	      return body.error;
53	    }
54	    return FALLBACK_ERROR;
55	  }
56	
57	  function showError(message) {
58	    errorBox.textContent = message;
59	  }
60	
61	  function createOption(name) {
62	    const option = document.createElement('option');
63	    option.value = name;
64	    option.textContent = name;
65	    return option;
66	  }
67	
68	  async function loadRooms() {
69	    const reply = await send('/api/rooms', { method: 'GET' });
70	    if (reply === null) {
71	      showError(UNREACHABLE);
72	      return;
73	    }
74	    if (reply.status !== 200) {
75	      showError(errorMessage(reply.body));
76	      return;
77	    }
78	    const rooms = isPlainObject(reply.body) ? reply.body.rooms : undefined;
79	    if (!Array.isArray(rooms)) {
80	      showError(FALLBACK_ERROR);
81	      return;
82	    }
83	    roomSelect.replaceChildren(...rooms.map(createOption));
84	  }
85	
86	  function createBookingItem(booking) {
87	    const item = document.createElement('li');
88	    const cancelButton = document.createElement('button');
89	    cancelButton.type = 'button';
90	    cancelButton.textContent = 'Cancel';
91	    cancelButton.addEventListener('click', () => {
92	      cancelBooking(booking.id, cancelButton);
93	    });
94	    item.append(`${booking.date} ${booking.start}-${booking.end} ${booking.room}: ${booking.title}`);
95	    item.append(cancelButton);
96	    return item;
97	  }
98	
99	  function createEmptyItem() {
100	    const item = document.createElement('li');
101	    item.append('No bookings.');
102	    return item;
103	  }
104	
105	  function renderList(bookings) {
106	    const items = bookings.length === 0
107	      ? [createEmptyItem()]
108	      : bookings.map(createBookingItem);
109	    bookingList.replaceChildren(...items);
110	  }
111	
112	  function listUrl() {
113	    const filter = filterDate.value;
114	    return filter === '' ? '/api/bookings' : '/api/bookings?date=' + filter;
115	  }
116	
117	  // Only the outcome of the most recently started list fetch is used.
118	  async function loadList() {
119	    listSequence += 1;
120	    const sequence = listSequence;
121	    const reply = await send(listUrl(), { method: 'GET' });
122	    if (sequence !== listSequence) {
123	      return;
124	    }
125	    if (reply === null) {
126	      showError(UNREACHABLE);
127	      return;
128	    }
129	    if (reply.status !== 200) {
130	      showError(errorMessage(reply.body));
131	      return;
132	    }
133	    const bookings = isPlainObject(reply.body) ? reply.body.bookings : undefined;
134	    if (!Array.isArray(bookings) || !bookings.every(isPlainObject)) {
135	      showError(FALLBACK_ERROR);
136	      return;
137	    }
138	    renderList(bookings);
139	  }
140	
141	  async function submitBooking() {
142	    if (bookButton.disabled) {
143	      return;
144	    }
145	    bookButton.disabled = true;
146	    const payload = {
147	      room: roomSelect.value,
148	      title: titleInput.value,
149	      date: dateInput.value,
150	      start: startInput.value,
151	      end: endInput.value,
152	    };
153	    const reply = await send('/api/bookings', {
154	      method: 'POST',
155	      headers: { 'Content-Type': 'application/json' },
156	      body: JSON.stringify(payload),
157	    });
158	    bookButton.disabled = false;
159	    if (reply === null) {
160	      showError(UNREACHABLE);
161	      return;
162	    }
163	    if (reply.status !== 201) {
164	      showError(errorMessage(reply.body));
165	      return;
166	    }
167	    titleInput.value = '';
168	    showError('');
169	    loadList();
170	  }
171	
172	  async function cancelBooking(id, button) {
173	    if (button.disabled) {
174	      return;
175	    }
176	    button.disabled = true;
177	    const reply = await send('/api/bookings/' + id, { method: 'DELETE' });
178	    button.disabled = false;
179	    if (reply === null) {
180	      showError(UNREACHABLE);
181	      return;
182	    }
183	    showError(reply.status === 204 ? '' : errorMessage(reply.body));
184	    loadList();
185	  }
186	
187	  form.addEventListener('submit', (event) => {
188	    event.preventDefault();
189	    submitBooking();
190	  });
191	
192	  filterDate.addEventListener('change', () => {
193	    loadList();
194	  });
195	
196	  showAllButton.addEventListener('click', () => {
197	    filterDate.value = '';
198	    loadList();
199	  });
200	
201	  loadRooms();
202	  loadList();
203	})();
204
